import {Heading, Link as PrimerLink} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import {isFeatureEnabled} from '@github-ui/feature-flags'

import {Link} from '@github-ui/react-core/link'
import SingleSelect from './dropdown/SingleSelect'
import {Sections} from '../components/State'
import {useId} from 'react'

import styles from './NotificationsSettings.module.css'
import {clsx} from 'clsx'

interface Props {
  emails: string[]
  defaultEmail: string
  isEmailReadonly?: boolean
  saveData: (section: Sections, formData: FormData) => void
}

function NotificationsSettings(props: Props) {
  const saveEmail = (email: string) => {
    if (isFeatureEnabled('track_notifications_settings_usage')) {
      sendEvent('notifications.settings.update', {
        section: 'notifications',
        event: 'default_email_update',
      })
    }
    const formData = new FormData()
    formData.set('email', email)
    props.saveData(Sections.Notifications, formData)
  }

  const defaultEmailLabelId = useId()
  const defaultEmailDescriptionId = useId()

  return (
    <>
      <div className={styles.NotificationsSettingsCard}>
        <Heading as="h3" id={defaultEmailLabelId} className={styles.NotificationsSettingsTitle}>
          Default notifications email
        </Heading>
        <p id={defaultEmailDescriptionId} className={styles.descriptionText}>
          {!props.isEmailReadonly
            ? "Choose where you'd like emails to be sent. You can add more email addresses. Use custom routes to specify different email addresses to be used for individual organizations."
            : 'Your email address is managed by your enterprise.'}
        </p>
        <div className={styles.emailSelectRow}>
          <SingleSelect
            options={props.emails}
            defaultOption={props.defaultEmail}
            onChange={saveEmail}
            disabled={props.isEmailReadonly ?? false}
            aria-labelledby={defaultEmailLabelId}
            aria-describedby={defaultEmailDescriptionId}
          />
          {!props.isEmailReadonly && (
            <PrimerLink
              as={Link}
              to="/settings/notifications/custom_routing"
              className={clsx('btn btn-sm', styles.PrimerLink)}
            >
              Custom routing
            </PrimerLink>
          )}
        </div>
      </div>
    </>
  )
}

export default NotificationsSettings
