    formData.set('vulnerability_cli', onSaveSelectedOptions.includes('vulnerabilityCli') ? '1' : '0')
    formData.set('vulnerability_email', onSaveSelectedOptions.includes('vulnerabilityEmail') ? '1' : '0')

