import type React from 'react'
import {useId} from 'react'

import {Heading} from '@primer/react'
import type {ActionProps} from '../ActionProps'

import styles from './Row.module.css'

export interface RowProps {
  title: string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  subtitle?: React.ComponentElement<any, any> | string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  renderAction?: <T extends ActionProps>(props: Required<ActionProps>) => React.ComponentElement<T, any>
  separator?: boolean
  sx?: React.CSSProperties
}

function Row(props: RowProps) {
  const labelId = useId()
  const descriptionId = useId()
  const actionId = useId()

  return (
    <div
      style={{
        borderBottomWidth: props.separator === false ? 0 : 1,
        ...props.sx,
      }}
      className={styles.rowContainer}
    >
      <div className={`mr-sm-0 ml-sm-0`}>
        <Heading as="h3" id={labelId} className={styles.rowTitle}>
          {props.title}
        </Heading>
        <span id={descriptionId} className={styles.rowSubtitle}>
          {props.subtitle}
        </span>
        {props.renderAction && (
          <div className={styles.rowActionContainer}>
            {props.renderAction({
              id: actionId,
              'aria-labelledby': `${labelId} ${actionId}`,
              'aria-describedby': descriptionId,
            })}
          </div>
        )}
      </div>
    </div>
  )
}

export default Row
